DROP TABLE IF EXISTS `production_cost`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `production_cost` (
  `cost_id` int NOT NULL AUTO_INCREMENT,
  `production_id` int NOT NULL,
  `job_id` int NOT NULL,
  `job_rate` decimal(10,2) NOT NULL,
  `job_discount` decimal(10,2) DEFAULT NULL,
  `cost_rate` decimal(10,2) NOT NULL,
  `cost_discount` decimal(10,2) DEFAULT NULL,
  `work_hours` decimal(6,2) NOT NULL,
  `cost_amount` decimal(10,2) NOT NULL,
  `is_active` enum('Y','N') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'Y',
  `is_delete` enum('Y','N') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'N',
  `create_date` datetime DEFAULT NULL,
  `create_by_id` smallint DEFAULT NULL,
  `create_ip` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `update_date` datetime DEFAULT NULL,
  `update_by_id` smallint DEFAULT NULL,
  `update_ip` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `delete_date` datetime DEFAULT NULL,
  `delete_by_id` smallint DEFAULT NULL,
  `delete_ip` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`cost_id`) USING BTREE,
  KEY `idx_production_id` (`production_id`) USING BTREE,
  KEY `idx_job_id` (`job_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=624 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;
